const customerMsg = $json.customer_message || 'Hello';
const promptText = `You are the automated Cognitive Routing Engine for an enterprise Customer Service platform. Analyze the incoming customer message and classify it.\n\nRules:\n1. If customer asks about order status, tracking, shipment, or mentions an order number (e.g. ORD-1001), classify intent as 'order_lookup' and extract order_number entity.\n2. If customer asks about policies, returns, refunds, shipping times, warranty, or general store questions, classify intent as 'faq_query'.\n3. If customer is angry, abusive, demands a supervisor, or expresses extreme frustration, classify intent as 'human_escalation' and set requires_human to true.\n4. Otherwise classify intent as 'general_support'.\n\nRespond STRICTLY with a valid JSON object matching this schema:\n{\n  "intent": "order_lookup" | "faq_query" | "human_escalation" | "general_support",\n  "confidence": 0.95,\n  "entities": { "order_number": "..." },\n  "sentiment": "positive" | "neutral" | "frustrated" | "angry",\n  "requires_human": false,\n  "direct_response": "friendly greeting or acknowledgment"\n}\n\nCustomer Message: ${JSON.stringify(customerMsg)}`;

return [{
  json: {
    ollama_body: {
      model: 'gemma2:2b',
      prompt: promptText,
      stream: false,
      format: 'json',
      options: {
        num_ctx: 1024,
        num_predict: 160
      }
    },
    customer_message: customerMsg,
    customer: $json.customer,
    conversation: $json.conversation
  }
}];

const rawResponse = $input.first()?.json?.response;
const originalInput = $('Build Prompt Payload').first().json;

let parsed = {};
try {
  parsed = JSON.parse(rawResponse);
} catch (e) {
  const msg = (originalInput.customer_message || '').toLowerCase();
  if (msg.includes('order') || msg.includes('track') || msg.includes('ord-')) {
    parsed = {
      intent: 'order_lookup',
      confidence: 0.85,
      entities: { order_number: (msg.match(/ord-\d+/i) || [])[0] || null },
      sentiment: 'neutral',
      requires_human: false,
      direct_response: 'Checking your order details...'
    };
  } else if (msg.includes('refund') || msg.includes('return') || msg.includes('warranty') || msg.includes('shipping')) {
    parsed = {
      intent: 'faq_query',
      confidence: 0.85,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: 'Looking up our store policies...'
    };
  } else if (msg.includes('human') || msg.includes('agent') || msg.includes('supervisor') || msg.includes('angry') || msg.includes('terrible') || msg.includes('furious')) {
    parsed = {
      intent: 'human_escalation',
      confidence: 0.95,
      entities: {},
      sentiment: 'frustrated',
      requires_human: true,
      direct_response: 'Connecting you with human support...'
    };
  } else {
    parsed = {
      intent: 'general_support',
      confidence: 0.70,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: 'Hello! How can I assist you today?'
    };
  }
}

if (!parsed.entities) { parsed.entities = {}; }
if (!parsed.entities.order_number) {
  const match = (originalInput.customer_message || '').match(/ord-\d+/i);
  if (match) { parsed.entities.order_number = match[0].toUpperCase(); }
}

return [{
  json: {
    ai_output: parsed,
    customer_message: originalInput.customer_message,
    customer: originalInput.customer,
    conversation: originalInput.conversation
  }
}];
